using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class PruneReportIntermediates {public static string Main(){if(Application.isPlaying)throw new Exception("Edit mode required");var notes=new List<string>();foreach(string scene in new[]{"MountainLoop","MountainLoopReverse"}){var s=EditorSceneManager.OpenScene("Assets/Scenes/"+scene+".unity");int count=0;foreach(var mf in UnityEngine.Object.FindObjectsByType<MeshFilter>().Where(m=>AssetDatabase.GetAssetPath(m.sharedMesh).StartsWith("Assets/Track/ReportCleanup/")&&m.sharedMesh.triangles.Length==0&&m.transform.childCount==0).ToArray()){if(mf.GetComponents<Component>().Any(c=>!(c is Transform||c is MeshFilter||c is MeshRenderer||c is MeshCollider)))continue;UnityEngine.Object.DestroyImmediate(mf.gameObject);count++;}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);notes.Add(scene+": empty generated support objects removed="+count);}if(File.Exists("Assets/ReportCleanupBaseline.unity"))AssetDatabase.DeleteAsset("Assets/ReportCleanupBaseline.unity");var scenes=Directory.GetFiles("Assets/Scenes","*.unity",SearchOption.AllDirectories);var required=new HashSet<string>(AssetDatabase.GetDependencies(scenes,true));long bytes=0;int files=0;AssetDatabase.StartAssetEditing();try{foreach(var raw in File.ReadAllLines("Temp/reportcleanup-untracked-assets.txt")){var p=raw.Trim();if(!p.EndsWith(".asset")||!File.Exists(p)||required.Contains(p))continue;if(!(p.StartsWith("Assets/Track/ReportCleanup/")||p.StartsWith("Assets/Track/BackyardReverse/MountainLoop")))continue;bytes+=new FileInfo(p).Length;notes.Add("Discard unused task-created intermediate "+p);if(!AssetDatabase.DeleteAsset(p))throw new Exception("Delete failed "+p);files++;}}finally{AssetDatabase.StopAssetEditing();}AssetDatabase.SaveAssets();notes.Add("Unreferenced task-created assets removed="+files+" bytes="+bytes+"; all saved production scene dependencies retained.");File.WriteAllLines("Docs/ReportCleanup/authoring-cleanup.txt",notes);return notes.Last();}}
